//! Compile generated Typst source to PDF bytes.
//!
//! Every line of the source is machine-generated by this crate, so a compile
//! error is a transform bug, not a user error. The diagnostic mapping
//! therefore optimizes for debuggability-from-a-log-line: each error carries
//! its 1-based line:column position plus the offending generated source line.

use typst::WorldExt;
use typst::diag::{Severity, SourceDiagnostic};
use typst_layout::PagedDocument;

use crate::error::RenderError;
use crate::typeset::world::{DappleWorld, VirtualAsset};

pub struct CompileJob<'a> {
    /// Complete generated Typst source (preamble + body + colophon).
    pub source: String,
    /// Virtual files referenced by the source (cover image, logo SVGs).
    pub assets: Vec<VirtualAsset>,
    /// Request-provided display date; feeds `datetime.today()` deterministically.
    pub date: Option<&'a str>,
}

/// Compile Typst source and export a PDF.
pub fn compile_typst(job: CompileJob) -> Result<Vec<u8>, RenderError> {
    let world = DappleWorld::new(job.source, job.assets, job.date);

    let result = typst::compile::<PagedDocument>(&world);
    for warning in &result.warnings {
        log::warn!("typst warning: {}", format_diagnostic(&world, warning));
    }
    let document = result.output.map_err(|errors| {
        let rendered: Vec<String> = errors
            .iter()
            .map(|e| format_diagnostic(&world, e))
            .collect();
        RenderError::TypstCompile(rendered.join("; "))
    })?;

    let bytes = typst_pdf::pdf(&document, &typst_pdf::PdfOptions::default()).map_err(|errors| {
        let rendered: Vec<String> = errors
            .iter()
            .map(|e| format_diagnostic(&world, e))
            .collect();
        RenderError::PdfGeneration(format!("PDF export failed: {}", rendered.join("; ")))
    })?;

    Ok(bytes)
}

/// Render one diagnostic with position + the generated source line, when the
/// span maps into the main source (detached spans fall back to message-only).
fn format_diagnostic(world: &DappleWorld, diag: &SourceDiagnostic) -> String {
    let severity = match diag.severity {
        Severity::Error => "error",
        Severity::Warning => "warning",
    };
    // The world holds exactly one source, so any resolvable range is in it.
    let source = world.main_source();
    let location = world
        .range(diag.span)
        .and_then(|range| {
            let (line_idx, col_idx) = source.lines().byte_to_line_column(range.start)?;
            let line_range = source.lines().line_to_range(line_idx)?;
            let line_text = source.text().get(line_range)?.trim_end();
            Some(format!(
                " at {}:{} in generated source: `{}`",
                line_idx + 1,
                col_idx + 1,
                truncate(line_text, 160)
            ))
        })
        .unwrap_or_default();

    let hints = if diag.hints.is_empty() {
        String::new()
    } else {
        let rendered: Vec<&str> = diag.hints.iter().map(|h| h.v.as_str()).collect();
        format!(" (hint: {})", rendered.join("; "))
    };

    format!("{severity}: {}{location}{hints}", diag.message)
}

fn truncate(s: &str, max: usize) -> &str {
    match s.char_indices().nth(max) {
        Some((idx, _)) => &s[..idx],
        None => s,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn minimal_source_compiles_to_pdf() {
        let job = CompileJob {
            source: "Hello, *world*.".to_string(),
            assets: vec![],
            date: None,
        };
        let bytes = compile_typst(job).expect("compile should succeed");
        assert!(bytes.starts_with(b"%PDF"), "not a PDF header");
        assert!(bytes.len() > 500);
    }

    #[test]
    fn errors_carry_generated_line_context() {
        let job = CompileJob {
            source: "Line one is fine.\n#no-such-function(1)\n".to_string(),
            assets: vec![],
            date: None,
        };
        let err = compile_typst(job).expect_err("compile should fail");
        let msg = err.to_string();
        assert!(msg.contains("Typst compile error"), "wrong variant: {msg}");
        assert!(msg.contains("at 2:"), "missing line info: {msg}");
        assert!(
            msg.contains("no-such-function"),
            "missing source line: {msg}"
        );
    }

    #[test]
    fn virtual_assets_resolve_for_images() {
        // A minimal valid SVG served as a virtual file (same decode path the
        // colophon wordmark uses).
        let svg = br##"<svg xmlns="http://www.w3.org/2000/svg" width="10" height="10"><rect width="10" height="10" fill="#49a013"/></svg>"##
            .to_vec();
        let job = CompileJob {
            source: "#image(\"/mark.svg\", width: 10pt)".to_string(),
            assets: vec![("mark.svg".to_string(), svg)],
            date: None,
        };
        let bytes = compile_typst(job).expect("image compile should succeed");
        assert!(bytes.starts_with(b"%PDF"));
    }
}
